'use client'

import './space-type.css'
import {
  getSpaceTypeGeometry,
  type SpaceTypeControls,
  type SpaceTypeGeometry,
  type SpaceTypeOptions,
  spaceType,
} from './motion/space-type.js'
import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { composeRefs } from './compose-refs.js'
import { useIsomorphicLayoutEffect } from './use-isomorphic-layout-effect.js'

export interface SpaceTypeProps
  extends SpaceTypeOptions,
    Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'color'> {
  text: string
  /** Number of stacked rings, from 1 to 6. @default 1 */
  rows?: number
  /** Text color; alternatively set --kida-space-type-color. */
  color?: string
  /** Surface color; alternatively set --kida-space-type-background. */
  background?: string
  /** Strength of the pulsing cylinder and tilting letter surface, from 0 to 100. @default 0 */
  longitude?: number
  /** Base radius in pixels, clamped to the available frame. Defaults to auto. */
  radius?: number
  /** Reports fitted geometry and the available radius range after measurement. */
  onGeometryChange?: (geometry: SpaceTypeGeometry | null) => void
}

export const SpaceType = forwardRef<HTMLDivElement, SpaceTypeProps>(function SpaceType(
  {
    text,
    speed = 1,
    paused = false,
    rows = 1,
    color,
    background,
    longitude = 0,
    radius,
    onGeometryChange,
    style,
    ...props
  },
  forwardedRef,
) {
  const rootRef = useRef<HTMLDivElement>(null)
  const controlsRef = useRef<SpaceTypeControls | null>(null)
  const [size, setSize] = useState({ width: 0, height: 0 })
  const rowCount = Number.isFinite(rows) ? Math.max(1, Math.min(6, Math.round(rows))) : 1
  const wave = Number.isFinite(longitude) ? Math.max(0, Math.min(100, longitude)) : 0
  const characters = Array.from(text)
  const geometry = useMemo(
    () => getSpaceTypeGeometry(size.width, size.height, characters.length, rowCount, wave, radius),
    [size.width, size.height, characters.length, rowCount, wave, radius],
  )

  useIsomorphicLayoutEffect(() => {
    const root = rootRef.current
    if (!root) return
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return
      const { width, height } = entry.contentRect
      setSize((current) =>
        current.width === width && current.height === height ? current : { width, height },
      )
    })
    observer.observe(root)
    const controls = spaceType(root)
    controlsRef.current = controls
    return () => {
      observer.disconnect()
      controls.destroy()
      controlsRef.current = null
    }
  }, [])

  useIsomorphicLayoutEffect(() => {
    controlsRef.current?.setPlayback({ speed, paused: paused || characters.length === 0 })
  }, [speed, paused, characters.length])

  useEffect(() => {
    onGeometryChange?.(geometry)
  }, [geometry, onGeometryChange])

  return (
    <div
      {...props}
      ref={composeRefs(rootRef, forwardedRef)}
      data-kida-space-type=""
      style={
        {
          '--kida-space-type-count': Math.max(characters.length, 1),
          '--kida-space-type-rows': rowCount,
          '--kida-space-type-longitude': wave,
          ...(color === undefined ? {} : { '--kida-space-type-color': color }),
          ...(background === undefined ? {} : { '--kida-space-type-background': background }),
          ...(geometry
            ? {
                '--kida-space-type-size': `${geometry.fontSize}px`,
                '--kida-space-type-radius': `${geometry.radius}px`,
                '--kida-space-type-perspective': `${geometry.perspective}px`,
              }
            : {}),
          ...style,
        } as CSSProperties
      }
    >
      <span data-kida-space-type-text="">{text}</span>
      <div data-kida-space-type-space="" aria-hidden="true">
        <div data-kida-space-type-camera="">
          <div data-kida-space-type-ring="">
            {Array.from({ length: rowCount }, (_, row) => (
              <div
                // biome-ignore lint/suspicious/noArrayIndexKey: row slots are stable positions without local state
                key={row}
                data-kida-space-type-row=""
                style={{ '--kida-space-type-row': row } as CSSProperties}
              >
                {characters.map((character, index) => (
                  <span
                    // biome-ignore lint/suspicious/noArrayIndexKey: glyph slots preserve rotation while editing text
                    key={index}
                    data-kida-space-type-letter=""
                    style={{ '--kida-space-type-index': index } as CSSProperties}
                  >
                    <span data-kida-space-type-face="front">{character}</span>
                    <span data-kida-space-type-face="back">{character}</span>
                  </span>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
})

import type { Ref } from 'react'

/** Feed one node to several refs — ours for measuring, Zag's for animation detection. */
export function composeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node)
      else if (ref) (ref as { current: T | null }).current = node
    }
  }
}

[data-kida-space-type] {
  --kida-space-type-color: #211c24;
  --kida-space-type-background: #fffafb;
  width: 100%;
  --kida-space-type-size: calc(
    min(9cqw, 350cqw / var(--kida-space-type-count), 20cqw / var(--kida-space-type-rows))
  );
  /* Reserve the strongest wave before measurement as well. */
  --kida-space-type-radius: calc(34cqw / 1.32);
  position: relative;
  container-type: inline-size;
  height: var(--kida-space-type-height, clamp(15rem, 40vw, 28rem));
  padding: 0;
  border: 0;
  overflow: clip;
  background: var(--kida-space-type-background);
}

[data-kida-space-type] [data-kida-space-type-space] {
  position: relative;
  width: 100%;
  height: 100%;
  user-select: none;
  pointer-events: none;
  perspective: var(--kida-space-type-perspective, 1200cqw);
}

[data-kida-space-type] [data-kida-space-type-camera],
[data-kida-space-type] [data-kida-space-type-ring],
[data-kida-space-type] [data-kida-space-type-row],
[data-kida-space-type] [data-kida-space-type-letter] {
  position: absolute;
  width: 0;
  height: 0;
  transform-style: preserve-3d;
}

[data-kida-space-type] [data-kida-space-type-camera] {
  top: 50%;
  left: 50%;
  transform: rotateX(18deg) rotateZ(-3deg);
}

[data-kida-space-type] [data-kida-space-type-ring] {
  transform: rotateY(-90deg);
}

[data-kida-space-type] [data-kida-space-type-row] {
  /* A wave travels along the cylinder's rows. Each letter follows its local slope. */
  --kida-space-type-wave-angle: calc(
    var(--kida-space-type-phase) *
    2880deg +
    var(--kida-space-type-row) *
    2160deg /
    var(--kida-space-type-count)
  );
  --kida-space-type-wave-amplitude: calc(
    var(--kida-space-type-radius) *
    var(--kida-space-type-longitude) *
    0.0032
  );
  --kida-space-type-row-radius: calc(
    var(--kida-space-type-radius) +
    sin(var(--kida-space-type-wave-angle)) *
    var(--kida-space-type-wave-amplitude)
  );
  --kida-space-type-surface-tilt: atan2(
    calc(
      var(--kida-space-type-wave-amplitude) *
      cos(var(--kida-space-type-wave-angle)) *
      sin(2160deg / var(--kida-space-type-count))
    ),
    calc(var(--kida-space-type-size) * 1.2)
  );
  transform: translateY(
    calc(
      (var(--kida-space-type-row) - (var(--kida-space-type-rows) - 1) / 2) *
      var(--kida-space-type-size) *
      1.2
    )
  );
}

[data-kida-space-type] [data-kida-space-type-letter] {
  transform: rotateY(calc(var(--kida-space-type-index) * 360deg / var(--kida-space-type-count)))
    translateZ(var(--kida-space-type-row-radius)) rotateX(var(--kida-space-type-surface-tilt));
}

[data-kida-space-type] [data-kida-space-type-face] {
  position: absolute;
  top: calc(var(--kida-space-type-size) * -0.5);
  left: calc(var(--kida-space-type-size) * -0.4);
  width: calc(var(--kida-space-type-size) * 0.8);
  height: var(--kida-space-type-size);
  backface-visibility: hidden;
  font-family: var(--kida-space-type-font, "Helvetica Neue", "Segoe UI", sans-serif);
  font-size: var(--kida-space-type-size);
  font-weight: 200;
  line-height: 1;
  text-align: center;
  white-space: pre;
}

[data-kida-space-type] [data-kida-space-type-face="front"] {
  color: var(--kida-space-type-color);
  transform: translateZ(0.1px) scaleX(0.7);
}

[data-kida-space-type] [data-kida-space-type-face="back"] {
  color: color-mix(in srgb, var(--kida-space-type-color) 30%, var(--kida-space-type-background));
  transform: rotateY(180deg) translateZ(0.1px) scaleX(-0.7);
}

[data-kida-space-type] [data-kida-space-type-text] {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@property --kida-space-type-phase {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

import { prefersReducedMotion, watchReducedMotion } from './reduced-motion.js'

export { getSpaceTypeGeometry, type SpaceTypeGeometry } from './space-type-geometry.js'

export interface SpaceTypeOptions {
  /** Rotation rate; zero freezes the current angle. @default 1 */
  speed?: number
  /** Pause without resetting the current angle. @default false */
  paused?: boolean
}

export interface SpaceTypeControls {
  setPlayback(options: SpaceTypeOptions): void
  destroy(): void
}

/** Shared loop lifecycle; adapters only render the geometry and update playback options. */
export function spaceType(root: HTMLElement, options: SpaceTypeOptions = {}): SpaceTypeControls {
  const ring = root.querySelector<HTMLElement>('[data-kida-space-type-ring]')
  let animation: Animation | undefined
  let visible = false
  let destroyed = false
  let speed = 1
  let paused = false

  const sync = () => {
    if (destroyed || !ring) return
    if (prefersReducedMotion()) {
      animation?.cancel()
      animation = undefined
      root.dataset.state = 'reduced'
      return
    }
    if (!animation) {
      animation = ring.animate(
        [
          { transform: 'rotateY(-90deg)', '--kida-space-type-phase': '0' },
          { transform: 'rotateY(270deg)', '--kida-space-type-phase': '1' },
        ],
        { duration: 24000, iterations: Number.POSITIVE_INFINITY, easing: 'linear' },
      )
      animation.pause()
    }
    if (animation.playbackRate !== speed) animation.updatePlaybackRate(speed)
    if (paused || speed === 0 || !visible || document.hidden) {
      animation.pause()
      root.dataset.state = 'paused'
    } else {
      animation.play()
      root.dataset.state = 'active'
    }
  }

  const setPlayback = (next: SpaceTypeOptions) => {
    speed = Number.isFinite(next.speed) ? Math.max(0, Math.min(3, next.speed ?? 1)) : 1
    paused = next.paused ?? false
    sync()
  }
  const observer = new IntersectionObserver(([entry]) => {
    visible = entry?.isIntersecting ?? false
    sync()
  })
  observer.observe(root)
  document.addEventListener('visibilitychange', sync)
  const unwatch = watchReducedMotion(sync)
  setPlayback(options)

  return {
    setPlayback,
    destroy() {
      destroyed = true
      observer.disconnect()
      document.removeEventListener('visibilitychange', sync)
      unwatch()
      animation?.cancel()
      animation = undefined
      root.dataset.state = 'idle'
    },
  }
}

const TILT = (18 * Math.PI) / 180
const ROLL = (3 * Math.PI) / 180
const PROJECTION_ALLOWANCE = 1.1
const RADIUS_RESERVE = 0.88
const MAX_WAVE = 0.32

/** Bounds reserve the full longitude wave, so its strength never changes the base radius. */
export function getSpaceTypeGeometry(
  width: number,
  height: number,
  characterCount: number,
  rows: number,
  _longitude: number,
  requestedRadius?: number,
) {
  if (width <= 0 || height <= 0) return null

  rows = Number.isFinite(rows) ? Math.max(1, Math.min(6, Math.round(rows))) : 1
  const count = Math.max(1, characterCount)
  const inset = Math.max(8, width * 0.018)
  const halfWidth = Math.max(0, width / 2 - inset) / PROJECTION_ALLOWANCE
  const halfHeight = Math.max(0, height / 2 - inset) / PROJECTION_ALLOWANCE
  const radialX = Math.cos(ROLL)
  const stackX = Math.sin(ROLL)
  const radialY = Math.hypot(Math.cos(TILT) * Math.sin(ROLL), Math.sin(TILT))
  const stackY = Math.cos(TILT) * Math.cos(ROLL)

  const radiusLimit = (fontSize: number, tilted = false) => {
    // Tilting the glyph surface can project half its height into the radial plane.
    const glyphRadialExtent = fontSize * (tilted ? 0.9 : 0.4)
    const stackHalfHeight = fontSize * ((rows - 1) * 0.6 + 0.5)
    return Math.max(
      0,
      Math.min(
        (halfWidth - stackHalfHeight * stackX) / radialX - glyphRadialExtent,
        (halfHeight - stackHalfHeight * stackY) / radialY - glyphRadialExtent,
      ),
    )
  }

  // Size type against the resting ring, independently of radius and wave strength.
  let fontSize = Math.min(width * 0.09, (width * 3.5) / count, (width * 0.2) / rows)
  const nominalRadius = width * 0.34
  const initialRadius = Math.min(nominalRadius, radiusLimit(fontSize) * RADIUS_RESERVE)
  if (count > 1) {
    fontSize = Math.min(fontSize, (2 * initialRadius * Math.sin(Math.PI / count)) / 0.7)
  }

  const maxRadius = radiusLimit(fontSize, true) / (1 + MAX_WAVE)
  const defaultRadius = Math.min(nominalRadius, maxRadius * RADIUS_RESERVE)
  // Compact rings intentionally pack the same-sized letters more densely.
  const minRadius = Math.min(maxRadius, (width * 0.1) / (1 + MAX_WAVE))
  const radius = Math.max(
    minRadius,
    Math.min(
      maxRadius,
      typeof requestedRadius === 'number' && Number.isFinite(requestedRadius)
        ? requestedRadius
        : defaultRadius,
    ),
  )

  return {
    fontSize,
    radius,
    minRadius,
    maxRadius,
    perspective: Math.max(width, height) * 12,
  }
}

export type SpaceTypeGeometry = NonNullable<ReturnType<typeof getSpaceTypeGeometry>>

const QUERY = '(prefers-reduced-motion: reduce)'

/**
 * Whether the user has asked for reduced motion.
 *
 * SSR-safe: returns `false` when there is no `window`, matching the CSS default
 * (the `prefers-reduced-motion` media query in `@kida-ui/styles` is the real guard;
 * this is for the JS-driven paths that CSS cannot express).
 */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false
  return window.matchMedia(QUERY).matches
}

/**
 * Subscribe to changes of the reduced-motion preference.
 * Returns an unsubscribe function. No-op (and immediately unsubscribable) on the server.
 */
export function watchReducedMotion(onChange: (reduced: boolean) => void): () => void {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return () => {}

  const list = window.matchMedia(QUERY)
  const handler = (event: MediaQueryListEvent) => onChange(event.matches)
  list.addEventListener('change', handler)
  return () => list.removeEventListener('change', handler)
}
